-- reput_metiers.sql — BANC (recette) : bases de connaissances REPUT réalistes pour cinq métiers (session C3, 18/10/2026).
--
-- Cinq métiers des pages /secteurs : dentaire, avocats, BTP, architectes, location automobile.
-- Fiches GÉNÉRIQUES reformulées d'après des FAQ et pages pratiques publiques d'entreprises et d'organismes réels
-- (source notée sur chaque fiche) ; aucune donnée personnelle, aucune donnée de santé individuelle, aucun prix
-- propre à une entreprise ; sites retenus seulement si robots.txt et mentions légales ne l'interdisent pas
-- (vérification ci-dessous). Toutes en BROUILLON sur le client du banc : elles n'entrent pas dans la base en
-- vigueur (rien n'est répondu depuis elles) tant qu'une personne ne les valide pas ; le titre porte le métier.
-- Rejouable : une fiche de même titre n'est pas reposée. Rien n'est effacé. 69 fiches.
--
-- Vérification des sources :
--   Dentaire : retenus — dentiste-sens.com (cabinet) : pas de robots.txt (404), aucune page de mentions légales trouvée ; service-public.gouv.fr : robots.txt autorise /particuliers/vosdroits/, licence etalab-2.0 ; mutualite-mfpa.fr : robots.txt autorise, mentions légales sans interdiction de réutilisation. Écartés : denteka.fr, cdnsm.fr, maisonyera.fr, centres-sante-lmg.fr (mentions légales interdisant reproduction/exploitation), ordre-chirurgiens-dentistes.fr (consultation privée seule), ameli.fr (robots.txt non vérifiable).
--   Avocats : retenus — service-public.gouv.fr (robots.txt permet /particuliers/vosdroits/, licence etalab-2.0) ; conseil-etat.fr (pas de robots.txt, informations publiques librement réutilisables, source citée) ; fr.wikipedia.org (CC BY-SA 4.0, attribution par URL). Écartés : cnb.avocat.fr, avocatparis.org, barreaulyon.com, barreau-marseille.avocat.fr, barreau-rouen.avocat.fr, mediateur-consommation-avocat.fr, inc-conso.fr, justice.gouv.fr, cnil.fr (CGU interdisant reproduction/adaptation ou usage commercial) ; justice.fr, legifrance, economie.gouv.fr, vie-publique.fr, courdecassation.fr (non consultables). Aucun cabinet privé retenu.
--   BTP : retenus — service-public.gouv.fr (robots.txt permet /particuliers/vosdroits/, Licence ouverte Etalab 2.0) ; fr.wikipedia.org (robots.txt permet /wiki/, CC BY-SA, fiches reformulées avec URL) ; impots.gouv.fr (robots.txt OK, Licence ouverte Etalab 2.0). Écartés : capeb.fr, ffbatiment.fr, anil.org, anah.gouv.fr, inc-conso.fr (mentions légales interdisant la reproduction) ; france-renov.gouv.fr, economie.gouv.fr, legifrance.gouv.fr, agirpourlatransition.ademe.fr, ecologie.gouv.fr (robots.txt non vérifiable). Aucun site d'entreprise du bâtiment retenu : ceux consultés interdisent la reproduction.
--   Architectes : retenus — service-public.gouv.fr et entreprendre.service-public.gouv.fr (robots.txt permet /vosdroits/, licence etalab-2.0 ; même éditeur DILA) ; culture.gouv.fr (robots.txt sans Disallow, licence Etalab 2.0). Écartés : architectes.org, caue13.fr, les-caue-occitanie.fr, fncaue.com, anil.org, inc-conso.fr, ffbatiment.fr (mentions légales exigeant une autorisation ou excluant l'usage commercial) ; caue-observatoire.fr, economie.gouv.fr, ecologie.gouv.fr, france-renov.gouv.fr (non vérifiables). Aucune agence privée retenue ; pas de fiche sur les honoraires ni le détail des missions (seule source : architectes.org, écartée).
--   Location auto : retenus — service-public.gouv.fr (robots.txt permet /particuliers/vosdroits, licence Etalab) ; lafinancepourtous.com (IEFP : robots.txt sans interdiction, mentions légales ne protégeant que la marque) ; faq.ada.fr — CAS LIMITE À TRANCHER : robots.txt permet /hc/fr/articles, les CG d'ada.fr disent que les textes appartiennent à ADA et n'interdisent expressément que la reproduction des marques, logos et images (7 fiches, entièrement reformulées, sans montant). Écartés : rentacar.fr, europcar.fr, avis.fr, ucar.fr, location.leclerc, inc-conso.fr, europe-consommateurs.eu, antai.gouv.fr (CGU interdisant extraction/reproduction ou usage commercial) ; sixt.fr, economie.gouv.fr, legifrance.gouv.fr, hertz.fr, getaround (non vérifiables).

do $$
declare
  v_client uuid := 'cccccccc-0000-4000-8000-00000000000c';
  v_n int := 0;
  f record;
begin
  if not exists (select 1 from public.reput_reglages r where r.client_id = v_client) then
    perform public.reput_installer(v_client);
  end if;
  for f in select * from (values
    ('urgence', 'question', '[Dentaire] Le cabinet reçoit-il les urgences dentaires ?', 'Le cabinet prend en charge les urgences. Les patients déjà suivis sont en général reçus vite, souvent dans la journée. Les nouveaux patients sont accueillis selon les disponibilités. Il vaut mieux appeler le cabinet dès que le problème apparaît, pour évaluer la situation.', 'Reformulé d''après http://www.dentiste-sens.com/index.php/le-cabinet-dentaire-du-mail/questions-frequentes/'),
    ('urgence', 'information', '[Dentaire] Quelles situations sont considérées comme une urgence dentaire ?', 'Sont notamment des urgences : une douleur très forte, un abcès ou un gonflement du visage, une dent cassée ou déplacée après un choc, un saignement qui ne s''arrête pas, la perte d''une couronne ou d''un pansement, une prothèse cassée ou perdue, ou une réaction allergique à un médicament. Dans ces cas, contactez le cabinet sans attendre.', 'Reformulé d''après http://www.dentiste-sens.com/index.php/soins-dentaires/urgence-dentaire/'),
    ('rendez_vous', 'information', '[Dentaire] Comment se déroule un premier rendez-vous ?', 'Le premier rendez-vous commence par un questionnaire médical et dentaire, puis un examen des dents et des gencives. Des radiographies peuvent être faites pour préciser le diagnostic. À la fin de la consultation, le praticien présente un plan de traitement. C''est aussi le moment de dire ce que l''on attend ou ce qui inquiète, et de poser ses questions.', 'Reformulé d''après http://www.dentiste-sens.com/index.php/soins-dentaires/consultation-dentaire/'),
    ('rendez_vous', 'document', '[Dentaire] Quels documents apporter à mon rendez-vous ?', 'Pensez à apporter votre carte Vitale et votre carte de mutuelle (complémentaire santé) à jour. À votre arrivée, présentez-vous à l''accueil.', 'Reformulé d''après https://www.mutualite-mfpa.fr/dentaire.html'),
    ('rendez_vous', 'question', '[Dentaire] Que faire si je ne peux pas venir à mon rendez-vous ?', 'En cas d''empêchement, prévenez le cabinet le plus tôt possible pour annuler ou déplacer votre rendez-vous : le créneau pourra être proposé à un autre patient. Selon le règlement du cabinet, un rendez-vous manqué sans prévenir peut entraîner l''annulation des rendez-vous suivants.', 'Reformulé d''après https://www.mutualite-mfpa.fr/dentaire.html'),
    ('tarifs', 'tarif', '[Dentaire] La consultation chez le dentiste est-elle remboursée ?', 'Oui. Dans le cas général, l''Assurance maladie rembourse les consultations et les soins faits par un chirurgien-dentiste à 60 % du tarif conventionnel (90 % en Alsace-Moselle avec le régime local). La complémentaire santé peut prendre en charge la différence, selon le contrat.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F33956'),
    ('devis', 'document', '[Dentaire] Le cabinet remet-il un devis avant une prothèse ?', 'Oui. Avant une prothèse ou un traitement d''orthodontie, le praticien remet un devis écrit, que le patient peut signer pour accord. Le devis précise le traitement et les matériaux, l''origine de fabrication de la prothèse, les honoraires, la part remboursée par l''Assurance maladie et, si elle existe, une solution sans reste à charge ou à reste à charge maîtrisé.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F33956'),
    ('devis', 'question', '[Dentaire] Pourquoi le cabinet ne donne-t-il pas le prix d''un traitement par téléphone ?', 'Pour un implant ou une prothèse, le prix dépend de la situation de chaque patient. Le praticien doit d''abord faire un examen, poser un diagnostic et établir un plan de traitement. Il peut ensuite remettre un devis détaillé.', 'Reformulé d''après http://www.dentiste-sens.com/index.php/le-cabinet-dentaire-du-mail/questions-frequentes/'),
    ('tarifs', 'question', '[Dentaire] Le cabinet pratique-t-il le tiers payant ?', 'Le tiers payant sur la part de l''Assurance maladie est proposé au choix du professionnel de santé : il n''y est pas obligé dans tous les cas. Les bénéficiaires de la complémentaire santé solidaire y ont droit sur présentation de leur carte Vitale à jour. Renseignez-vous auprès du cabinet quand vous prenez rendez-vous.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F167'),
    ('information', 'question', '[Dentaire] Ma mutuelle ne m''a pas remboursé comme prévu, que faire ?', 'Seul l''assuré peut faire une réclamation auprès de sa mutuelle. Contactez-la avec le devis et la réponse qu''elle y avait donnée, pour obtenir des explications.', 'Reformulé d''après http://www.dentiste-sens.com/index.php/le-cabinet-dentaire-du-mail/questions-frequentes/'),
    ('tarifs', 'information', '[Dentaire] Qu''est-ce que le « 100 % Santé » en dentaire ?', 'Le 100 % Santé regroupe des couronnes, des bridges et des dentiers remboursés en totalité par l''Assurance maladie et la complémentaire santé, sans reste à charge. Il existe aussi un panier à tarifs maîtrisés, aux prix plafonnés, et un panier à tarifs libres. Le devis indique la solution sans reste à charge ou à reste à charge maîtrisé, si elle existe.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F33956'),
    ('suivi', 'information', '[Dentaire] Qu''est-ce que l''examen « M''T dents tous les ans ! » ?', 'Les jeunes de 3 à 24 ans ont droit chaque année à un examen de prévention bucco-dentaire gratuit. Ils n''avancent pas de frais pour cet examen ni pour les soins faits dans les 6 mois qui suivent (hors prothèses, inlay-onlay et orthodontie). Signalez-le en prenant rendez-vous, et apportez la carte Vitale, la carte de mutuelle et, pour un enfant, son carnet de santé.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F243'),
    ('suivi', 'question', '[Dentaire] À quel âge amener son enfant chez le dentiste pour la première fois ?', 'Une première visite est possible dès l''apparition des premières dents ; en pratique, on la prévoit souvent entre 4 et 6 ans. Un suivi régulier permet ensuite de repérer tôt les caries, qui ne font pas toujours mal.', 'Reformulé d''après http://www.dentiste-sens.com/index.php/le-cabinet-dentaire-du-mail/questions-frequentes/'),
    ('rendez_vous', 'question', '[Avocats] À quoi sert le premier rendez-vous avec le cabinet ?', 'Le premier rendez-vous permet au cabinet d''analyser votre situation, de vous expliquer les règles applicables et les risques, et d''évoquer, le cas échéant, une solution amiable. L''avocat peut aussi déconseiller une action qui lui paraît vouée à l''échec. Il ne garantit jamais un résultat, mais un accompagnement éclairé et loyal.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2153'),
    ('devis', 'document', '[Avocats] Le cabinet doit-il me faire signer une convention d''honoraires ?', 'Oui. Sauf urgence ou force majeure, la loi impose une convention d''honoraires écrite, rédigée en termes clairs. Elle précise le montant ou le mode de calcul des honoraires au regard des diligences prévisibles, ainsi que les frais et débours envisagés. Le cabinet vous la remet avant d''engager le travail.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F15018'),
    ('tarifs', 'tarif', '[Avocats] Comment les honoraires du cabinet sont-ils calculés ?', 'Les honoraires sont libres et fixés d''un commun accord. Ils peuvent être calculés au temps passé (taux horaire multiplié par les heures consacrées au dossier) ou au forfait (montant global, souvent pour les affaires simples). Un honoraire complémentaire de résultat peut s''y ajouter s''il est prévu à l''avance dans la convention.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F15018'),
    ('tarifs', 'question', '[Avocats] Le cabinet peut-il être payé uniquement en fonction du résultat du procès ?', 'Non. La loi interdit de fixer la totalité des honoraires sur le seul résultat judiciaire (« pacte de quota litis »). Un honoraire de résultat, en pourcentage ou forfaitaire, est en revanche possible en complément d''une rémunération des prestations, s''il est convenu par écrit à l''avance et reste raisonnable.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F932'),
    ('tarifs', 'question', '[Avocats] Pourquoi le cabinet demande-t-il une provision avant de commencer ?', 'Il est d''usage que l''avocat demande une provision, c''est-à-dire une avance sur ses frais et honoraires, avant de prendre en charge un dossier. À défaut de règlement, l''avocat peut refuser de prendre en charge l''affaire.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F15018'),
    ('information', 'information', '[Avocats] Puis-je bénéficier de l''aide juridictionnelle ?', 'L''aide juridictionnelle permet aux personnes aux ressources modestes de faire prendre en charge par l''État tout ou partie des frais de justice et des honoraires d''avocat. Elle dépend de plafonds de ressources et n''est accordée que si aucune assurance de protection juridique ne couvre déjà les frais. La demande, avec justificatifs, est adressée au bureau d''aide juridictionnelle.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F18074'),
    ('tarifs', 'question', '[Avocats] Avec l''aide juridictionnelle totale, le cabinet peut-il me demander des honoraires ?', 'En principe non : en cas d''aide juridictionnelle totale, la rémunération versée par l''État à l''avocat exclut toute autre somme à la charge du client. Le bénéficiaire reste libre de choisir son avocat, qui est lui-même libre d''accepter ou non le dossier ; à défaut, le bâtonnier peut en désigner un.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F15006'),
    ('tarifs', 'information', '[Avocats] Que se passe-t-il si l''aide juridictionnelle n''est que partielle ?', 'Avec une aide juridictionnelle partielle, l''État ne prend en charge qu''une fraction des coûts. Le complément d''honoraires restant à la charge du client est alors convenu avec l''avocat et prévu dans une convention d''honoraires.', 'Reformulé d''après https://fr.wikipedia.org/wiki/Aide_juridictionnelle_en_France'),
    ('information', 'information', '[Avocats] Ce que je confie au cabinet reste-t-il confidentiel ?', 'Oui. Les échanges entre l''avocat et son client sont couverts par le secret professionnel, qui est général, absolu et sans limite dans le temps. Il ne peut être levé que dans des cas strictement prévus par la loi, par exemple pour la propre défense de l''avocat.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2153'),
    ('suivi', 'information', '[Avocats] Comment le cabinet me tient-il informé de l''avancement de mon dossier ?', 'L''avocat traite le dossier avec diligence et vous informe régulièrement de son évolution. Il agit dans les limites de votre mandat et sollicite votre accord pour les décisions importantes, comme une transaction. À la clôture, il vous remet un compte détaillé distinguant sa rémunération et les frais avancés, et vous restitue les pièces du dossier.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2153'),
    ('suivi', 'question', '[Avocats] Puis-je changer d''avocat en cours de dossier ?', 'Oui, le client peut changer d''avocat à tout moment, y compris en cours de procédure. Les honoraires correspondant au travail déjà accompli restent dus, et l''ancien avocat doit transmettre l''intégralité du dossier. En cas de difficulté, le bâtonnier de l''ordre peut être saisi.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F14724'),
    ('suivi', 'question', '[Avocats] Que faire en cas de désaccord sur les honoraires ?', 'Il est conseillé d''en parler d''abord par écrit avec l''avocat pour trouver un accord amiable. À défaut, le client peut saisir gratuitement le médiateur de la consommation de la profession d''avocat, ou demander au bâtonnier de l''ordre de fixer les honoraires ; la décision du bâtonnier peut faire l''objet d''un recours devant le premier président de la cour d''appel.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F14724'),
    ('urgence', 'question', '[Avocats] Un proche est en garde à vue : comment obtenir un avocat rapidement ?', 'La personne gardée à vue peut demander l''assistance d''un avocat à l''officier de police judiciaire, en désignant un avocat choisi ou en sollicitant un avocat commis d''office désigné par le bâtonnier. L''avocat commis d''office n''est pas gratuit par principe : ses honoraires sont dus, sauf prise en charge au titre de l''aide juridictionnelle.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F36104'),
    ('information', 'information', '[Avocats] Le cabinet peut-il proposer une médiation plutôt qu''un procès ?', 'Oui, la médiation permet de rechercher un accord amiable avec l''aide d''un médiateur neutre et indépendant, avant ou pendant une procédure. Elle repose sur l''accord des parties, chacune pouvant y mettre fin, et ses échanges sont confidentiels : ils ne peuvent pas être invoqués devant le juge si elle échoue. Son coût est souvent inférieur à celui d''un procès.', 'Reformulé d''après https://www.conseil-etat.fr/vos-demarches/je-suis-un-particulier/recourir-a-la-mediation'),
    ('devis', 'question', '[BTP] Le devis est-il gratuit ?', 'Le devis est en général gratuit. Il peut toutefois être facturé lorsqu''il demande un déplacement ou une étude particulière. Dans tous les cas, l''entreprise indique avant de l''établir s''il est gratuit ou payant et, s''il est payant, son coût.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2533'),
    ('devis', 'document', '[BTP] Que doit contenir un devis de travaux ?', 'Le devis détaille chaque prestation (nature des travaux, quantités, prix unitaires), le taux horaire de main-d''œuvre, les frais de déplacement, le total HT et TTC avec le taux de TVA, sa durée de validité et son caractère gratuit ou payant. Si le chantier produit des déchets, il précise aussi leur enlèvement, leur traitement et leur coût.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2533'),
    ('devis', 'question', '[BTP] Quand le devis devient-il un engagement ferme ?', 'Le devis vaut contrat dès qu''il est signé par le client et par l''entreprise, avec la mention « bon pour travaux » ou « bon pour accord » au-dessus de la signature du client. Chacune des deux parties conserve un exemplaire original daté et signé.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2533'),
    ('tarifs', 'tarif', '[BTP] Faut-il verser un acompte à la signature ?', 'Le devis peut prévoir un acompte ou des arrhes, et précise lequel des deux s''applique. L''acompte engage fermement les deux parties. Avec des arrhes, chacun peut renoncer : le client perd alors les arrhes versées, l''entreprise doit rembourser le double si c''est elle qui se désiste.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2533'),
    ('devis', 'question', '[BTP] Peut-on se rétracter après avoir signé un devis ?', 'Un devis signé à distance ou après un démarchage à domicile ouvre un délai de rétractation de 14 jours, à exercer par lettre recommandée avec accusé de réception. Un devis signé dans les locaux de l''entreprise ne permet pas de se rétracter.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2533'),
    ('urgence', 'question', '[BTP] Pour un dépannage urgent (fuite, panne), un devis est-il nécessaire ?', 'Oui : en plomberie, électricité, serrurerie ou chauffage, l''entreprise doit remettre un devis avant un dépannage ou une réparation. En revanche, le délai de rétractation de 14 jours ne s''applique pas aux travaux et réparations d''urgence, par exemple une fuite d''eau.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2533'),
    ('rendez_vous', 'question', '[BTP] Une visite technique a-t-elle lieu avant le devis ?', 'Elle est souvent utile pour évaluer le chantier. Pour les travaux de rénovation énergétique aidés par MaPrimeRénov'' qui exigent une entreprise qualifiée RGE, la visite préalable est obligatoire : elle sert à vérifier que les matériaux et équipements conviennent au logement, et sa date doit figurer sur le devis.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F35083'),
    ('information', 'document', '[BTP] L''entreprise fournit-elle une attestation d''assurance décennale ?', 'Oui. Avant l''ouverture du chantier, l''entreprise remet au client une attestation de son assurance de responsabilité civile décennale. Cette attestation doit aussi être jointe au devis et à la facture. Elle mentionne les coordonnées de l''assureur, utiles si un sinistre survient plus tard.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2034'),
    ('information', 'question', '[BTP] Que couvre la garantie décennale ?', 'Pendant 10 ans après la réception, la garantie décennale couvre les dommages qui compromettent la solidité de l''ouvrage ou le rendent impropre à son usage (fissures importantes, défaut d''un équipement indissociable du bâti comme une canalisation ou une installation électrique encastrée…). Elle s''applique aux constructions neuves comme aux travaux d''extension ou de rénovation.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2034'),
    ('suivi', 'question', '[BTP] Qu''est-ce que la garantie de parfait achèvement ?', 'Pendant un an à compter de la réception, l''entreprise doit réparer tous les désordres signalés dans le procès-verbal de réception ou apparus ensuite. Cette garantie légale ne peut pas être écartée par le contrat. Elle ne couvre pas l''usure normale.', 'Reformulé d''après https://fr.wikipedia.org/wiki/Garantie_de_parfait_ach%C3%A8vement'),
    ('suivi', 'question', '[BTP] Qu''est-ce que la garantie biennale (bon fonctionnement) ?', 'Pendant deux ans après la réception, l''entreprise doit réparer ou remplacer les éléments d''équipement qui ne fonctionnent pas correctement, à condition qu''ils puissent être retirés sans abîmer le bâti (par exemple un ballon d''eau chaude). Les éléments indissociables relèvent de la garantie décennale.', 'Reformulé d''après https://fr.wikipedia.org/wiki/Garantie_de_bon_fonctionnement_(droit_fran%C3%A7ais)'),
    ('suivi', 'information', '[BTP] Comment se passe la réception des travaux ?', 'À la fin du chantier, le client et l''entreprise constatent ensemble les travaux et signent un procès-verbal de réception, avec ou sans réserves. Un défaut visible non signalé à ce moment est considéré comme accepté. La réception fait démarrer les garanties de parfait achèvement, biennale et décennale.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2958'),
    ('information', 'question', '[BTP] Le client doit-il souscrire une assurance dommages-ouvrage ?', 'Avant un chantier de construction, d''extension ou de rénovation confié à une entreprise, le maître d''ouvrage doit obligatoirement souscrire une assurance dommages-ouvrage. Elle finance la réparation des dommages relevant de la garantie décennale, sans recherche préalable des responsabilités.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F2032'),
    ('tarifs', 'tarif', '[BTP] Quel taux de TVA s''applique aux travaux dans un logement ?', 'Dans un logement achevé depuis plus de deux ans, les travaux d''amélioration ou d''entretien peuvent relever du taux réduit de 10 %, et les travaux de rénovation énergétique du taux de 5,5 %, sous conditions. Le client certifie par une mention sur le devis ou la facture que les conditions sont remplies. Les autres cas restent au taux normal.', 'Reformulé d''après https://www.impots.gouv.fr/professionnel/questions/quel-taux-de-tva-appliquer-pour-les-travaux-realises-dans-les-logements'),
    ('information', 'question', '[Architectes] Le recours à un architecte est-il obligatoire pour construire ma maison ?', 'Pour un particulier qui construit pour lui-même, l''architecte est obligatoire dès que la surface de plancher dépasse 150 m² (800 m² pour un bâtiment agricole). En dessous de ce seuil, il reste facultatif, mais l''agence peut tout de même concevoir le projet et préparer le dossier de permis de construire.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F20568'),
    ('information', 'question', '[Architectes] Pour une extension, comment savoir si l''architecte devient obligatoire ?', 'Le seuil de 150 m² s''apprécie sur la surface de plancher totale de la construction, existant compris. Si la maison dépasse 150 m² après travaux, ou déjà avant travaux lorsque l''extension relève du permis de construire, le recours à un architecte est obligatoire. L''agence peut vérifier ce calcul dès le premier échange.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F20568'),
    ('information', 'question', '[Architectes] Une SCI ou une société doit-elle passer par un architecte ?', 'Oui. Une personne morale (société, SCI…) doit faire appel à un architecte pour tout projet soumis à permis de construire, quelle que soit la surface. Seules les exploitations et coopératives agricoles bénéficient de seuils spécifiques.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F20568'),
    ('information', 'question', '[Architectes] Faut-il un architecte pour une simple déclaration préalable de travaux ?', 'Non, le recours à un architecte n''est jamais obligatoire pour un projet soumis à déclaration préalable. L''agence peut néanmoins être sollicitée pour concevoir le projet, établir les plans et constituer le dossier.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F20568'),
    ('suivi', 'information', '[Architectes] Combien de temps dure l''instruction d''un permis de construire ?', 'Une fois le dossier complet, la mairie dispose en règle générale de 2 mois pour une maison individuelle et de 3 mois pour les autres projets ; ces délais sont allongés en secteur protégé. Sans réponse à l''issue du délai, le permis est en principe accordé tacitement, sauf cas particuliers.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F1986'),
    ('suivi', 'information', '[Architectes] Que se passe-t-il si la mairie juge le dossier incomplet ?', 'La mairie dispose d''un mois après le dépôt pour réclamer les pièces manquantes. Le demandeur a alors 3 mois pour les fournir, faute de quoi la demande est rejetée, et le délai d''instruction ne court qu''à compter du dossier complet. L''agence se charge de réunir et transmettre les compléments.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F1986'),
    ('information', 'document', '[Architectes] Quelles pièces composent un dossier de permis de construire ?', 'Le dossier comprend le formulaire Cerfa, un plan de situation, un plan de masse, un plan en coupe, une notice descriptive, les plans des façades et toitures, une insertion graphique et des photographies de l''environnement proche et lointain, ainsi que l''attestation RE 2020 le cas échéant. D''autres pièces peuvent être exigées selon le projet.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F1986'),
    ('suivi', 'information', '[Architectes] Quel est le délai d''instruction d''une déclaration préalable ?', 'Pour un dossier complet, le délai d''instruction d''une déclaration préalable est en général d''un mois à compter du dépôt, et de deux mois en secteur protégé. Le dépôt peut se faire en ligne lorsque la commune le propose, par courrier recommandé ou directement en mairie.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F17578'),
    ('information', 'information', '[Architectes] Combien de temps un permis de construire reste-t-il valable ?', 'Le permis est valable 3 ans à compter de sa notification. Il devient caduc si les travaux ne commencent pas dans ce délai ou s''ils sont interrompus plus d''un an. Il peut être prolongé deux fois d''un an si les règles d''urbanisme n''ont pas changé, à condition d''en faire la demande au moins 2 mois avant l''échéance.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F1986'),
    ('suivi', 'information', '[Architectes] Faut-il afficher le permis de construire sur le terrain ?', 'Oui. Dès la notification de l''autorisation et pendant toute la durée du chantier, un panneau lisible depuis la voie publique doit être installé sur le terrain. Il mentionne notamment le numéro et la date du permis, la nature du projet et les informations sur les délais de recours.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F1986'),
    ('information', 'information', '[Architectes] Quelles assurances un architecte doit-il obligatoirement détenir ?', 'Tout architecte doit être couvert par une assurance de responsabilité civile professionnelle et par une assurance décennale, qui couvre les dommages apparaissant dans les 10 ans suivant la réception des travaux. L''attestation d''assurance décennale doit figurer sur les devis et factures ; l''agence peut la transmettre sur simple demande.', 'Reformulé d''après https://entreprendre.service-public.gouv.fr/vosdroits/F38232'),
    ('information', 'question', '[Architectes] Comment vérifier qu''il s''agit bien d''un architecte ?', 'Le titre d''architecte est protégé : il est réservé aux personnes inscrites au tableau de l''Ordre des architectes, et celui de société d''architecture aux sociétés inscrites. L''inscription au conseil régional de l''Ordre est obligatoire avant d''exercer et vaut pour tout le territoire national.', 'Reformulé d''après https://entreprendre.service-public.gouv.fr/vosdroits/F38232'),
    ('devis', 'question', '[Architectes] Un contrat écrit est-il signé avec l''agence ?', 'Oui. Le code de déontologie de la profession prévoit la signature d''un contrat écrit entre l''architecte et son client. Ce contrat fixe le cadre de la mission confiée à l''agence.', 'Reformulé d''après https://entreprendre.service-public.gouv.fr/vosdroits/F38232'),
    ('rendez_vous', 'document', '[Architectes] Que préparer avant un premier rendez-vous pour un projet en site protégé ?', 'Il est utile de se renseigner d''abord auprès de la mairie, par exemple via un certificat d''urbanisme, pour savoir si le terrain est en site protégé. Pour le premier rendez-vous, apportez si possible un plan de situation, des photos proches et éloignées du bâti, d''éventuels devis et vos échanges avec la mairie : l''agence s''en sert pour préparer le dossier soumis à l''avis de l''architecte des Bâtiments de France.', 'Reformulé d''après https://www.culture.gouv.fr/catalogue-des-demarches-et-subventions/mes-travaux-en-site-protege/2.-preparer-mon-projet'),
    ('information', 'document', '[Location auto] Quels documents faut-il présenter pour louer un véhicule ?', 'Le conducteur principal présente un permis de conduire en cours de validité correspondant au véhicule loué, une pièce d''identité et une carte bancaire à son nom. Un justificatif de domicile récent peut aussi être demandé selon les conditions de l''agence. L''attestation provisoire de réussite au permis n''est en général pas acceptée.', 'Reformulé d''après https://faq.ada.fr/hc/fr/articles/360017965453-Particulier-Documents-%C3%A0-pr%C3%A9senter'),
    ('information', 'question', '[Location auto] Quel âge et quelle ancienneté de permis faut-il pour louer ?', 'L''âge minimum et le nombre d''années de permis dépendent de la catégorie du véhicule et des conditions du loueur. Certains modèles, comme les monospaces ou les plus grands utilitaires, exigent une ancienneté de permis plus importante. Il est conseillé de vérifier ces conditions auprès de l''agence avant de réserver.', 'Reformulé d''après https://faq.ada.fr/hc/fr/articles/360017962813-Quel-est-le-nombre-minimum-d-ann%C3%A9es-de-permis-requis'),
    ('tarifs', 'question', '[Location auto] Peut-on louer avec une carte de débit plutôt qu''une carte de crédit ?', 'Beaucoup de loueurs exigent une carte de crédit (à débit différé) au nom du conducteur principal lors de la prise du véhicule ; une carte de débit peut être refusée. Il est préférable de vérifier avec l''agence avant le jour du départ quels moyens de paiement sont acceptés pour la location et le dépôt de garantie.', 'Reformulé d''après https://www.lafinancepourtous.com/outils/questions-reponses/puis-je-louer-une-voiture-sans-carte-de-credit/'),
    ('tarifs', 'tarif', '[Location auto] Comment fonctionne le dépôt de garantie ?', 'Un dépôt de garantie, généralement sous forme de pré-autorisation sur la carte bancaire du conducteur principal, est demandé au départ. Son montant dépend de la catégorie du véhicule et de la franchise prévue au contrat. En l''absence de dommage ou de frais complémentaires, il est libéré après la restitution du véhicule, dans le délai indiqué par l''agence.', 'Reformulé d''après https://faq.ada.fr/hc/fr/articles/360017965673-Quelles-sont-les-modalit%C3%A9s-de-d%C3%A9p%C3%B4t-de-garantie'),
    ('tarifs', 'information', '[Location auto] Qu''est-ce que la franchise et le rachat de franchise ?', 'La franchise est la somme qui reste à la charge du locataire en cas de dommage au véhicule ou de vol. Son montant figure dans le contrat et varie selon la catégorie du véhicule. Le rachat de franchise est une option facultative, partielle ou totale, qui réduit cette somme ; il faut en lire les conditions et exclusions avant de la souscrire.', 'Reformulé d''après https://www.lafinancepourtous.com/pratique/vacances-connaitre-ses-droits/location-de-voiture-le-rachat-de-franchise/'),
    ('information', 'information', '[Location auto] Quelle assurance est incluse dans une location de véhicule ?', 'La loi impose au loueur d''assurer le véhicule en responsabilité civile, incluse dans le prix : elle couvre les dommages causés aux tiers. Elle ne couvre ni les dommages au véhicule loué, ni les blessures du conducteur, ni le vol. Des garanties complémentaires facultatives peuvent être proposées ; l''agence doit en préciser les conditions, franchises et tarifs avant la signature.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F23420'),
    ('information', 'question', '[Location auto] Ma carte bancaire ou mon assurance couvre-t-elle déjà la location ?', 'Certaines cartes bancaires haut de gamme ou assurances personnelles incluent des garanties proches de celles proposées par les loueurs (dommages, vol, assistance). Il est utile de vérifier ses propres contrats avant de souscrire une option complémentaire auprès de l''agence.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F23420'),
    ('information', 'question', '[Location auto] Peut-on circuler à l''étranger avec le véhicule loué ?', 'Avant de sortir de France, même brièvement, il faut vérifier dans le contrat que l''assurance couvre bien le ou les pays visés et que le loueur autorise ce déplacement. Il est conseillé d''en informer l''agence au moment de la réservation.', 'Reformulé d''après https://www.service-public.gouv.fr/particuliers/vosdroits/F23420'),
    ('tarifs', 'information', '[Location auto] Comment fonctionne le carburant pendant la location ?', 'Le carburant n''est généralement pas compris dans le prix. Le véhicule doit être rendu avec le même niveau de carburant qu''au départ, tel qu''indiqué sur le contrat. À défaut, la différence est facturée, souvent avec des frais de service, selon les conditions de l''agence.', 'Reformulé d''après https://faq.ada.fr/hc/fr/articles/360017800894-Quelle-est-la-politique-concernant-le-carburant-pour-une-location-de-vehicule'),
    ('tarifs', 'information', '[Location auto] Le kilométrage est-il inclus et que se passe-t-il en cas de retard de restitution ?', 'Le prix couvre la mise à disposition du véhicule pour la durée et le kilométrage prévus au contrat ; les kilomètres supplémentaires sont facturés selon le tarif de l''agence. La durée est celle de la réservation : garder le véhicule au-delà entraîne une facturation supplémentaire. En cas de retard prévisible, il est conseillé de prévenir l''agence.', 'Reformulé d''après https://faq.ada.fr/hc/fr/articles/360017964413-Quelle-dur%C3%A9e-de-location'),
    ('information', 'question', '[Location auto] Peut-on ajouter un conducteur additionnel ou louer pour quelqu''un d''autre ?', 'La location est nominative : le locataire est le conducteur principal et la sous-location est interdite. Des conducteurs additionnels peuvent être inscrits au contrat s''ils remplissent les mêmes conditions d''âge et de permis et présentent leurs documents. Seules les personnes inscrites au contrat sont assurées ; un supplément peut s''appliquer selon l''agence.', 'Reformulé d''après https://faq.ada.fr/hc/fr/articles/7301578423580-Puis-je-louer-une-voiture-pour-quelqu-un-d-autre'),
    ('information', 'information', '[Location auto] Pourquoi l''état des lieux du véhicule est-il important ?', 'Au départ, le locataire signe un état des lieux qui recense les dommages déjà présents (rayures, chocs…). Il est recommandé de faire le tour du véhicule et de faire ajouter tout défaut non mentionné avant de partir. Un état des lieux est également réalisé au retour pour comparer l''état du véhicule.', 'Reformulé d''après https://www.lafinancepourtous.com/pratique/vacances-connaitre-ses-droits/location-de-voiture-le-rachat-de-franchise/'),
    ('urgence', 'information', '[Location auto] Que faire en cas d''accident, de panne ou de vol du véhicule loué ?', 'En cas d''accident avec un tiers, remplissez un constat amiable signé par les deux parties ; sans tiers, rédigez une déclaration des circonstances. Prévenez l''agence sans attendre et contactez l''assistance indiquée au contrat en cas de panne. En cas de vol, déclarez-le à la police ou à la gendarmerie et informez l''agence dans le délai prévu au contrat.', 'Reformulé d''après https://faq.ada.fr/hc/fr/articles/360017964833-Quelles-sont-mes-obligations-en-cas-de-vol-ou-d-accident'),
    ('rendez_vous', 'question', '[Location auto] Comment annuler une réservation et que se passe-t-il si je ne me présente pas ?', 'Les conditions d''annulation figurent dans les conditions de location de l''agence : une annulation faite suffisamment tôt peut être remboursée, parfois avec des frais, alors qu''une annulation tardive peut ne pas l''être. Si le véhicule n''est pas retiré à la date et à l''heure prévues, l''agence peut conserver le prix de la location.', 'Reformulé d''après https://faq.ada.fr/hc/fr/articles/360017965893-Comment-faire-si-je-ne-peux-pas-me-pr%C3%A9senter-%C3%A0-l-agence-le-jour-du-d%C3%A9part-de-la-location')
  ) as x(sujet, genre, titre, contenu, source)
  loop
    if not exists (select 1 from public.reput_connaissances k where k.client_id = v_client and k.titre = f.titre) then
      insert into public.reput_connaissances (id, client_id, origine_id, sujet, genre, titre, contenu, source, statut)
      select g.id, v_client, g.id, f.sujet, f.genre, f.titre, f.contenu, f.source, 'brouillon' from (select gen_random_uuid() as id) g;
      v_n := v_n + 1;
    end if;
  end loop;
  raise notice 'REPUT métiers : % fiche(s) posée(s) en brouillon sur le banc.', v_n;
end $$;
